<template>
  <div class="feedback-desk">
    <div class="feedback-metrics">
      <button type="button" @click="filter('pending')"><span>等待审核</span><strong>{{ counts.pending || 0 }}<small>条</small></strong><p>先读想法，再决定公示</p></button>
      <button type="button" @click="filter('published')"><span>正在征集</span><strong>{{ counts.published || 0 }}<small>条</small></strong><p>跑者投票，运营评估</p></button>
      <button type="button" @click="filter('adopted')"><span>已采纳</span><strong>{{ counts.adopted || 0 }}<small>条</small></strong><p>查看已采纳的想法</p></button>
      <button type="button" @click="filter('rewards')"><span>奖励待寄出</span><strong>{{ rewardsPending }}<small>份</small></strong><p>已登记收件信息</p></button>
    </div>
    <section class="feedback-workspace">
      <div class="feedback-toolbar"><div><h2>每个好想法，都有回音</h2><p>投票是评估参考，采纳时指定实物奖励，发货后登记物流。</p></div><form @submit.prevent="search"><label class="feedback-search"><span>搜索建议</span><input v-model="query" aria-label="搜索建议" placeholder="搜索标题或想法" maxlength="100" /></label><button type="submit">搜索</button></form></div>
      <div class="feedback-filters" role="group" aria-label="建议状态"><button v-for="item in filters" :key="item.value" type="button" :class="{on:status === item.value}" @click="filter(item.value)">{{ item.label }}<small v-if="item.value in counts">{{ counts[item.value] }}</small></button></div>
      <p v-if="error" class="feedback-error" role="alert">{{ error }} <button type="button" @click="load">重新加载</button></p>
      <p v-if="loading" class="feedback-empty" role="status">正在读取建议…</p>
      <template v-else>
        <div v-if="items.length" class="feedback-rows">
          <button v-for="item in items" :key="item.id" :data-feedback-id="item.id" class="feedback-admin-row" type="button" @click="open(item.id)">
            <div class="feedback-votes"><b>{{ item.votes }}</b><span>支持</span></div>
            <div class="feedback-row-copy"><div class="feedback-tags"><span>{{ categoryLabels[item.category] || '其他' }}</span><span>{{ moduleLabels[item.module] || '其他' }}</span><i :class="item.status">{{ item.statusLabel }}</i></div><h3>{{ item.title }}</h3><p>{{ item.author?.nickname }} · {{ date(item.createdAt) }}<span v-if="item.reward"> · {{ item.reward.name }} / {{ item.reward.statusLabel }}</span></p></div>
            <span class="feedback-open">处理 <AdminIcon name="chevron" /></span>
          </button>
        </div>
        <div v-else-if="!error" class="feedback-empty"><AdminIcon name="feedback" /><h3>这里还没有建议</h3><p>{{ status === 'pending' ? '用户提交的功能与 UI 想法会出现在这里。' : '可以切换其他状态，或调整搜索词。' }}</p></div>
        <div v-if="pages > 1" class="feedback-pager"><button type="button" :disabled="page <= 1" @click="changePage(-1)">上一页</button><span>{{ page }} / {{ pages }} · {{ total }} 条</span><button type="button" :disabled="page >= pages" @click="changePage(1)">下一页</button></div>
      </template>
    </section>
    <div v-if="detailOpen" class="feedback-detail-mask" @click.self="close" @keydown.esc="close">
      <section ref="detailPanel" class="feedback-admin-detail" role="dialog" aria-modal="true" aria-labelledby="feedback-review-title" tabindex="-1">
        <header><div><span>共创建议 #{{ detail?.id || '…' }}</span><h2 id="feedback-review-title">{{ detail?.title || '正在打开建议' }}</h2></div><button type="button" aria-label="关闭建议" :disabled="saving" @click="close"><AdminIcon name="close" /></button></header>
        <p v-if="detailError" class="feedback-error" role="alert">{{ detailError }}<button v-if="!saving" type="button" @click="open(selectedId)">重新读取建议</button></p>
        <div v-if="detail" class="feedback-detail-content">
          <div class="feedback-tags"><span>{{ categoryLabels[detail.category] }}</span><span>{{ moduleLabels[detail.module] }}</span><i :class="detail.status">{{ detail.statusLabel }}</i></div>
          <p class="feedback-byline">{{ detail.author?.nickname }} · {{ date(detail.createdAt) }} · {{ detail.votes }} 人支持</p>
          <p class="feedback-body">{{ detail.body }}</p>
          <div v-if="detail.images?.length" class="feedback-images"><a v-for="image in detail.images" :key="image.id" :href="image.url" target="_blank" rel="noopener noreferrer"><img :src="image.url" alt="用户提交的建议截图" /></a></div>
          <section v-if="detail.events?.length" class="feedback-history"><h3>公开进度</h3><div v-for="(event,index) in detail.events" :key="index"><span>{{ date(event.createdAt) }} · {{ event.statusLabel }}</span><p v-if="event.reply">{{ event.reply }}</p></div></section>
          <form class="feedback-review-form" @submit.prevent="save">
            <h3>回复与处理</h3>
            <label>处理结果<select v-model="nextStatus" :disabled="saving"><option v-for="item in availableStates" :key="item.value" :value="item.value">{{ item.label }}</option></select></label>
            <label>公开回复<textarea v-model="reply" rows="4" maxlength="2000" placeholder="说明评估结果、下一步安排或上线内容，避免填写联系方式。" :disabled="saving" /></label>
            <label v-if="nextStatus === 'adopted' && detail.status === 'published'">实物奖励<input v-model="rewardName" minlength="2" maxlength="80" placeholder="例如：跑步腰包一份（确认可兑现后填写）" required :disabled="saving" /><small>采纳后向作者开放领取，奖品承诺会公开展示。</small></label>
            <p class="feedback-hint">{{ nextStatus === 'published' && detail.status === 'pending' ? '公示后，建议正文和截图会向所有访客展示，请先确认不含个人敏感信息。' : '回复向作者展示；已公示建议的处理进度同时公开。' }}</p>
            <button type="submit" class="feedback-primary" :disabled="saving">{{ saving ? '正在保存…' : nextStatus === detail.status ? '更新回复' : '确认' + (statusLabels[nextStatus] || '') }}</button>
          </form>
          <section v-if="detail.reward" class="feedback-reward-desk">
            <div class="feedback-section-title"><h3>实物奖励</h3><span>{{ detail.reward.statusLabel }}</span></div><p class="feedback-reward-name">{{ detail.reward.name }}</p>
            <p v-if="detail.reward.status === 'unclaimed'" class="feedback-hint">等待作者在「我的建议」中填写收件信息。</p>
            <dl v-else class="feedback-address"><dt>收件人</dt><dd>{{ detail.reward.receiver }}</dd><dt>手机</dt><dd>{{ detail.reward.phone }}</dd><dt>地址</dt><dd>{{ detail.reward.address }}</dd></dl>
            <form v-if="detail.reward.status === 'claimed'" @submit.prevent="ship"><label>承运商<input v-model="carrier" placeholder="填写实际快递公司" minlength="2" maxlength="40" required :disabled="saving" /></label><label>物流单号<input v-model="tracking" placeholder="填写实际发货单号" minlength="4" maxlength="80" pattern="[A-Za-z0-9-]+" required :disabled="saving" /></label><p class="feedback-hint">核对奖品和收件信息后再确认。物流单号仅作者与平台管理员可见。</p><button type="submit" class="feedback-primary" :disabled="saving">{{ saving ? '正在登记…' : '确认发货并登记物流' }}</button></form>
            <p v-else-if="detail.reward.carrier" class="feedback-logistics">{{ detail.reward.carrier }} · {{ detail.reward.tracking }}</p>
          </section>
          <p v-if="notice" class="feedback-success" role="status">{{ notice }}</p>
        </div>
      </section>
    </div>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import AdminIcon from './AdminIcon.vue';
const props = defineProps({ request: { type: Function, required: true }, refreshKey: { type: Number, default: 0 }, initialFilter: { type: String, default: 'pending' } });
const emit = defineEmits(['changed']);
const statusLabels = {pending:'待审核',published:'征集中',adopted:'已采纳',building:'开发中',released:'已上线',declined:'暂不采纳',withdrawn:'已撤回'};
const filters = [{value:'all',label:'全部'},...Object.entries(statusLabels).map(([value,label])=>({value,label})),{value:'rewards',label:'奖励待寄'}];
const categoryLabels = {feature:'功能建议',ui:'UI 设计',bug:'问题反馈',other:'其他想法'};
const moduleLabels = {races:'赛事',clubs:'跑团',sport:'运动',profile:'我的',other:'其他'};
const status=ref(props.initialFilter), query=ref(''), searchQuery=ref(''), page=ref(1), pages=ref(1), total=ref(0), items=ref([]), counts=ref({}), rewardsPending=ref(0), loading=ref(false), error=ref('');
const detailOpen=ref(false), detail=ref(null), selectedId=ref(0), detailError=ref(''), detailPanel=ref(null), nextStatus=ref(''), reply=ref(''), rewardName=ref(''), carrier=ref(''), tracking=ref(''), saving=ref(false), notice=ref('');
let loadVersion=0, detailVersion=0, previousOverflow='', opener=null;
const availableStates=computed(()=>{const current=detail.value?.status;return [current,...({pending:['published','declined'],published:['adopted','declined'],adopted:['building','released'],building:['released']}[current] || [])].filter(Boolean).map(value=>({value,label:statusLabels[value]}))});
function date(value) { const parsed=new Date(value); return Number.isFinite(parsed.getTime()) ? parsed.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}) : '—'; }
async function load() { const version=++loadVersion; loading.value=true;error.value='';try {const data=await props.request('/admin/feedback?'+new URLSearchParams({status:status.value,q:searchQuery.value,page:String(page.value)}));if(version!==loadVersion)return;items.value=data.items;counts.value=data.counts;rewardsPending.value=data.rewardsPending || 0;total.value=data.total;pages.value=data.pages;page.value=data.page;}catch(err){if(version===loadVersion)error.value=err.message;}finally{if(version===loadVersion)loading.value=false;} }
function filter(value){status.value=value;page.value=1;load();}
function search(){searchQuery.value=query.value.trim();page.value=1;load();}
function changePage(delta){page.value+=delta;load();}
async function open(id){const version=++detailVersion;selectedId.value=id;detailError.value='';notice.value='';detail.value=null;if(!detailOpen.value){opener=document.activeElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';detailOpen.value=true;}await nextTick();detailPanel.value?.focus();try{const data=await props.request('/admin/feedback/'+id);if(version!==detailVersion)return;setDetail(data);}catch(err){if(version===detailVersion)detailError.value=err.message;}}
function setDetail(data){detail.value=data;nextStatus.value=data.status;reply.value=data.reply || '';rewardName.value=data.reward?.name || '';carrier.value=data.reward?.carrier || '';tracking.value=data.reward?.tracking || '';}
async function close(){if(saving.value)return;detailVersion++;detailOpen.value=false;document.body.style.overflow=previousOverflow;await nextTick();const target=opener?.isConnected?opener:document.querySelector('.feedback-admin-row[data-feedback-id="'+Number(selectedId.value)+'"]');target?.focus?.();}
async function save(){if(saving.value)return;detailError.value='';notice.value='';if(nextStatus.value!==detail.value.status && nextStatus.value!=='published' && reply.value.trim().length<2){detailError.value='请说明这次处理的结果与原因。';return;}saving.value=true;try{setDetail(await props.request('/admin/feedback/'+detail.value.id,{method:'PATCH',body:JSON.stringify({status:nextStatus.value,reply:reply.value,rewardName:rewardName.value,expectedVersion:detail.value.revision})}));notice.value='处理结果已保存。';await load();emit('changed');}catch(err){detailError.value=err.message;await nextTick();detailPanel.value?.scrollTo({top:0,behavior:"smooth"});}finally{saving.value=false;}}
async function ship(){if(saving.value)return;detailError.value='';notice.value='';saving.value=true;try{setDetail(await props.request('/admin/feedback/'+detail.value.id+'/reward/ship',{method:'POST',body:JSON.stringify({carrier:carrier.value,tracking:tracking.value,expectedVersion:detail.value.revision})}));notice.value='物流已登记，作者可以在建议详情查看。';await load();emit('changed');}catch(err){detailError.value=err.message;await nextTick();detailPanel.value?.scrollTo({top:0,behavior:"smooth"});}finally{saving.value=false;}}
function trapFocus(event){if(!detailOpen.value || event.key!=='Tab')return;const nodes=[...detailPanel.value.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey && (document.activeElement===first || document.activeElement===detailPanel.value)){event.preventDefault();last.focus();}else if(!event.shiftKey && document.activeElement===last){event.preventDefault();first.focus();}}
document.addEventListener('keydown',trapFocus);
watch(()=>props.refreshKey,()=>load());
watch(()=>props.initialFilter,value=>{status.value=value;page.value=1;load();});
onBeforeUnmount(()=>{loadVersion++;detailVersion++;document.removeEventListener('keydown',trapFocus);if(detailOpen.value)document.body.style.overflow=previousOverflow;});
load();
</script>

